import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers (clinical/stratum variables)
    clinical_vars = [fid for fid, typ in zip(feats.ids, feats.types) if typ == 'clinical']

    if not clinical_vars:
        # No clinical variables, use all features
        candidates = list(feats.ids)
    else:
        # Use clinical variables as potential drivers
        candidates = clinical_vars

    # Filter out near-duplicates based on correlation
    keep = []
    used = set()
    for fid in candidates:
        if fid in used:
            continue
        keep.append(fid)
        # Find correlated features to exclude
        for other_fid in candidates:
            if other_fid != fid and other_fid not in used:
                col_idx1 = feats.column(fid)
                col_idx2 = feats.column(other_fid)
                try:
                    corr = np.corrcoef(feats.x[:, col_idx1], feats.x[:, col_idx2])[0,1]
                    if abs(corr) >= 0.6:
                        used.add(other_fid)
                except:
                    pass

    # Compute effect sizes using t-tests
    effect_sizes = {}
    for fid in keep:
        col_idx = feats.column(fid)
        try:
            y0 = feats.x[feats.y==0, col_idx]
            y1 = feats.x[feats.y==1, col_idx]
            if len(y0) > 0 and len(y1) > 0:
                tstat, _ = stats.ttest_ind(y0, y1, equal_var=False)
                effect_sizes[fid] = abs(tstat)
        except:
            pass

    # Sort by effect size
    sorted_features = sorted(effect_sizes.items(), key=lambda x: x[1], reverse=True)

    # Select top drivers (max MAX_DRIVERS)
    drivers = tuple(fid for fid, _ in sorted_features[:MAX_DRIVERS])

    # If we have a driver, adjust for it in feature selection
    if drivers:
        # Get remaining features
        remaining = [fid for fid in feats.ids if fid not in drivers]
        remaining_cols = [feats.column(fid) for fid in remaining]

        # Use mutual information to select features
        try:
            if len(remaining) > 0:
                remaining_data = feats.x[:, remaining_cols]
                mi_scores = mutual_info_classif(remaining_data, feats.y)
                selected_indices = np.argsort(mi_scores)[::-1][:min(10, len(remaining))]
                selected_features = [remaining[i] for i in selected_indices]
            else:
                selected_features = []
        except:
            selected_features = remaining[:10] if remaining else []

        # Check for interactions
        products = []
        for i, fid1 in enumerate(selected_features):
            for j, fid2 in enumerate(selected_features[i+1:], i+1):
                # Check if interaction term would be useful
                col1 = feats.column(fid1)
                col2 = feats.column(fid2)
                try:
                    interaction = feats.x[:, col1] * feats.x[:, col2]
                    # Simple check: if interaction improves model significantly
                    lr1 = LogisticRegression(penalty='l1', solver='liblinear', fit_intercept=True, max_iter=1000)
                    lr2 = LogisticRegression(penalty='l1', solver='liblinear', fit_intercept=True, max_iter=1000)

                    # Fit with just main effects
                    lr1.fit(feats.x[:, col1].reshape(-1,1), feats.y)
                    # Fit with interaction
                    lr2.fit(np.hstack([feats.x[:, col1].reshape(-1,1), interaction.reshape(-1,1)]), feats.y)

                    if lr2.score(np.hstack([feats.x[:, col1].reshape(-1,1), interaction.reshape(-1,1)]), feats.y) > \
                       lr1.score(feats.x[:, col1].reshape(-1,1), feats.y) + 0.01:
                        products.append((fid1, fid2))
                except:
                    pass

        return Design(
            drivers=drivers,
            columns=tuple(selected_features),
            products=tuple(products),
            loadings={fid: 1.0 for fid in selected_features}
        )

    # No driver case - simple approach
    # Just return top features by effect size
    top_features = tuple(fid for fid, _ in sorted_features[:MAX_DRIVERS])

    # For no mechanism case, return empty drivers
    if not top_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Simple approach: use all features with high effect sizes
    # Return top features as columns
    return Design(
        drivers=(),
        columns=top_features,
        products=(),
        loadings={fid: 1.0 for fid in top_features}
    )
